  put.add(FAM2,Bytes.toBytes("letters"),Bytes.toBytes("hijklmnop"));
  table.put(put);
  long times[]=new long[3];
  Scan scan=new Scan();
  scan.addFamily(FAM1);
  scan.addFamily(FAM2);
  ResultScanner s=table.getScanner(scan);
  try {
    int index=0;
    Result r=null;
    while ((r=s.next()) != null) {
      for (      KeyValue key : r.sorted()) {
        times[index++]=key.getTimestamp();
      }
    }
  }
  finally {
    s.close();
  }
  for (int i=0; i < times.length - 1; i++) {
