public void testColumnCompare() throws Exception {
  final byte[] a=Bytes.toBytes("aaa");
  byte[] family1=Bytes.toBytes("abc");
  byte[] qualifier1=Bytes.toBytes("def");
  byte[] family2=Bytes.toBytes("abcd");
