  assertTrue(aaa.matchingColumn(family1,qualifier1));
  aaa=new KeyValue(a,family2,qualifier2,0L,Type.Put,a);
  assertFalse(aaa.matchingColumn(family1,qualifier1));
  assertTrue(aaa.matchingColumn(family2,qualifier2));
